CREATE OR REPLACE FUNCTION public.whatsapp_wake() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.whatsapp_messages WHERE status='pending') THEN IF NOT EXISTS(SELECT 1 FROM cron.job WHERE jobname='jannah-whatsapp-retry') THEN PERFORM cron.schedule('jannah-whatsapp-retry','0 * * * *',$job$ SELECT net.http_post(url:='https://project--f96d0623-3d94-4c29-b904-ecb9c33dfe92.lovable.app/api/public/hooks/whatsapp',headers:=jsonb_build_object('Content-Type','application/json','x-service-token',(SELECT token::text FROM public.service_tokens WHERE name='reminders')),body:='{}'::jsonb); $job$); END IF; PERFORM net.http_post(url:='https://project--f96d0623-3d94-4c29-b904-ecb9c33dfe92.lovable.app/api/public/hooks/whatsapp',headers:=jsonb_build_object('Content-Type','application/json','x-service-token',(SELECT token::text FROM public.service_tokens WHERE name='reminders')),body:='{}'::jsonb); END IF; RETURN NEW; EXCEPTION WHEN OTHERS THEN RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.whatsapp_delivery_valid(p_token text,p_kind text,p_payload jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.whatsapp_authorize(p_token);
 IF p_kind IN ('reminder','confirmation','reschedule') THEN RETURN EXISTS(SELECT 1 FROM public.appointments WHERE id=(p_payload->>'appointmentId')::uuid AND status='confirmado' AND day=(p_payload->>'day')::date AND start_time=(p_payload->>'start')::time AND (p_kind<>'reminder' OR day>(now() AT TIME ZONE 'America/Sao_Paulo')::date)); END IF;
 IF p_kind='prebooking' THEN RETURN EXISTS(SELECT 1 FROM public.appointments WHERE id=(p_payload->>'appointmentId')::uuid AND status='pendente'); END IF;
 IF p_kind='loyalty' THEN RETURN coalesce((SELECT loyalty_enabled FROM public.app_settings WHERE id),true); END IF;
 IF p_kind='due' THEN RETURN EXISTS(SELECT 1 FROM public.store_order_installments WHERE id=(p_payload->>'installmentId')::uuid AND paid_at IS NULL AND amount_cents>coalesce(paid_amount_cents,0)); END IF;
 IF p_kind='receipt' THEN RETURN EXISTS(SELECT 1 FROM public.store_order_installments WHERE id=(p_payload->>'installmentId')::uuid AND paid_amount_cents>0); END IF;
 RETURN true; END $$;